import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Assembly and Structured Presentation","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/assembly.md","filePath":"en/modules/corelib/assembly.md","lastUpdated":0}`),a={name:`en/modules/corelib/assembly.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="assembly-and-structured-presentation" tabindex="-1">Assembly and Structured Presentation <a class="header-anchor" href="#assembly-and-structured-presentation" aria-label="Permalink to “Assembly and Structured Presentation”">​</a></h1><p>Assembly rebuilds final item display from structured module layers. This prevents modules from overwriting each other&#39;s lore.</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to “Core concepts”">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Meaning</th></tr></thead><tbody><tr><td>namespace layer</td><td>One module&#39;s data layer on an item, holding all state that module writes.</td></tr><tr><td>order</td><td>The layer&#39;s sort weight, deciding where that module appears in the final lore.</td></tr><tr><td>snapshot</td><td>A snapshot of layer data, used for encoding, decoding, and persistence.</td></tr><tr><td>contribution</td><td>What a layer contributes to the final presentation: lore sections, name decoration, and attribute totals.</td></tr><tr><td>renderer</td><td>Merges every contribution into the final <code>ItemMeta</code>.</td></tr></tbody></table><h2 id="common-layers" tabindex="-1">Common layers <a class="header-anchor" href="#common-layers" aria-label="Permalink to “Common layers”">​</a></h2><table tabindex="0"><thead><tr><th>Namespace</th><th>Order</th><th>Meaning</th></tr></thead><tbody><tr><td><code>forge</code></td><td><code>100</code></td><td>Forge layer: quality, material contribution, forge recipe info.</td></tr><tr><td><code>strengthen</code></td><td><code>200</code></td><td>Strengthening layer: stars, forge mark, protection state, strengthen attributes.</td></tr><tr><td><code>gem</code></td><td><code>300</code></td><td>Gem layer: sockets, gems, levels, gem attributes.</td></tr><tr><td><code>cooking</code></td><td><code>10000</code></td><td>Cooking display layer or special presentation.</td></tr></tbody></table><p>Lower order appears earlier. CoreLib reads all registered layers and renders the final name and lore.</p><h2 id="assembly-flow" tabindex="-1">Assembly flow <a class="header-anchor" href="#assembly-flow" aria-label="Permalink to “Assembly flow”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. A module finishes an operation (strengthen success, gem inlay, ...)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. The module writes real state into PDC (layer snapshot)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. The module runs name_actions / lore_actions through ItemOperationLedger</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. The ledger records the operation into PDC (emaki:item_operations) for precise reverts</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>5. The updated ItemStack is returned</span></span></code></pre></div><p>Reverting an operation, such as gem extraction or a strengthening downgrade:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. The module calls Ledger.revert(operationId) or Ledger.revertAll(sourceNamespace)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. The reverter undoes exactly the recorded name / lore changes</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. Other modules&#39; results are left untouched</span></span></code></pre></div><h2 id="key-services" tabindex="-1">Key services <a class="header-anchor" href="#key-services" aria-label="Permalink to “Key services”">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Description</th></tr></thead><tbody><tr><td><code>EmakiItemAssemblyService</code></td><td>Assembly entry point; accepts rebuild requests and coordinates layers.</td></tr><tr><td><code>ItemOperationLedger</code></td><td>Unified name/lore operation ledger supporting precise reverts.</td></tr><tr><td><code>ItemOperationExecutor</code></td><td>Runs <code>name_actions</code> / <code>lore_actions</code> and records the changes.</td></tr><tr><td><code>ItemOperationReverter</code></td><td>Reverts operations from the ledger records.</td></tr><tr><td><code>EmakiNamespaceRegistry</code></td><td>Namespace registration and ordering for every registered layer.</td></tr><tr><td><code>EmakiItemLayerCodecRegistry</code></td><td>Layer encoding, decoding, and version migration.</td></tr></tbody></table><p>Namespace IDs are normalised on registration: trimmed, lowercased, spaces replaced with underscores, and a blank ID becomes <code>unknown</code>.</p><h2 id="name-contributions" tabindex="-1">Name contributions <a class="header-anchor" href="#name-contributions" aria-label="Permalink to “Name contributions”">​</a></h2><p>Layers may also decorate the item name. The position enum values are <code>PREFIX</code> and <code>POSTFIX</code> (there is no <code>SUFFIX</code>); an unknown or blank value falls back to <code>POSTFIX</code>.</p><h2 id="lore-operation-ledger" tabindex="-1">Lore operation ledger <a class="header-anchor" href="#lore-operation-ledger" aria-label="Permalink to “Lore operation ledger”">​</a></h2><p>Each <code>name_actions</code> / <code>lore_actions</code> execution is recorded under the item PDC key <code>emaki:item_operations</code> with an <code>operationId</code> and a <code>sourceNamespace</code>, so a single module&#39;s changes can be reverted precisely:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>apply(itemStack, operationId, sourceNamespace, nameActions, loreActions, variables)</code></td><td>Execute the operations and record them into PDC.</td></tr><tr><td><code>revert(itemStack, operationId)</code></td><td>Revert one specific operation.</td></tr><tr><td><code>revertAll(itemStack, sourceNamespace)</code></td><td>Revert every operation from one namespace.</td></tr></tbody></table><h2 id="insert-anchor-behaviour" tabindex="-1">Insert anchor behaviour <a class="header-anchor" href="#insert-anchor-behaviour" aria-label="Permalink to “Insert anchor behaviour”">​</a></h2><p>An empty <code>anchor</code> and an <code>anchor</code> that matches nothing do not behave the same way:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Empty <code>anchor</code></th><th><code>anchor</code> matches nothing</th></tr></thead><tbody><tr><td><code>insert_below</code></td><td>Insert at the end of the lore.</td><td>Insert at the end of the lore.</td></tr><tr><td><code>insert_above</code></td><td>Insert at the start of the lore.</td><td>Insert at the end of the lore.</td></tr></tbody></table><p>Anchors use <strong>contains</strong> matching and stop at the first matching line.</p><h2 id="when-assembly-is-triggered" tabindex="-1">When assembly is triggered <a class="header-anchor" href="#when-assembly-is-triggered" aria-label="Permalink to “When assembly is triggered”">​</a></h2><p>These operations rebuild an item:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Triggering module</th></tr></thead><tbody><tr><td>Strengthen success or failure</td><td>EmakiStrengthen</td></tr><tr><td>Forge completion</td><td>EmakiForge</td></tr><tr><td>Gem inlay / extraction / upgrade</td><td>EmakiGem</td></tr><tr><td>Automatic item update</td><td>EmakiItem</td></tr><tr><td>Manual refresh command</td><td>Any module</td></tr><tr><td>Attribute sync</td><td>EmakiAttribute</td></tr></tbody></table><h2 id="what-operators-can-change" tabindex="-1">What operators can change <a class="header-anchor" href="#what-operators-can-change" aria-label="Permalink to “What operators can change”">​</a></h2><p>Operators rarely touch the assembly service directly, but several settings shape its result.</p><p>Lore templates usually live in each module&#39;s own config:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># EmakiStrengthen example</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Strengthen level: &lt;yellow&gt;+%star%&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Strengthen bonus: &lt;green&gt;+%bonus_attack% attack&#39;</span></span></code></pre></div><p>Attribute display format is defined in EmakiAttribute&#39;s <code>lore_formats/</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># lore_formats/default_flat.yml</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;%display_name%: &lt;white&gt;+%value%&#39;</span></span></code></pre></div><p>Some modules expose display toggles:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_quality</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_material_info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_star_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_gem_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Existing gear does not update its presentation automatically after a config change. Use the module&#39;s refresh command to refresh one item, refresh online players in bulk, or rely on login-time refresh where the module supports it.</p><h2 id="presentation-design-advice" tabindex="-1">Presentation design advice <a class="header-anchor" href="#presentation-design-advice" aria-label="Permalink to “Presentation design advice”">​</a></h2><ul><li><strong>Keep real values in PDC or the attribute payload, not only in lore.</strong> Lore is the presentation layer; PDC is the data layer.</li><li><strong>Show only what players need.</strong> Internal debug data does not belong in lore.</li><li><strong>Keep each module&#39;s lore block clearly bounded.</strong> Forge, strengthen, and gem sections should not interleave.</li><li><strong>Do not let two modules print the same attribute.</strong> Show attack power in one place so players do not misread it.</li><li><strong>Sample-refresh old gear on a test server first</strong> when upgrading templates, to confirm old data still renders.</li><li><strong>Keep name decoration short.</strong> <code>+10 Flame Blade [Epic]</code> reads better than <code>[+10][Epic][Forged][Gem x3] Flame Blade</code>.</li></ul><h2 id="advice" tabindex="-1">Advice <a class="header-anchor" href="#advice" aria-label="Permalink to “Advice”">​</a></h2><p>Store real state in PDC or payloads. Use lore only as presentation. When a module changes item state, request a proper refresh.</p>`,39)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};